const body = $json;
const executions = body.data || [];

const total = executions.length;
const errored = executions.filter(e => e.status === 'error' || e.status === 'failed').length;
const error_rate_percentage = total ? Math.round((errored / total) * 1000) / 10 : 0;

const durations = executions
  .filter(e => e.startedAt && e.stoppedAt)
  .map(e => (new Date(e.stoppedAt).getTime() - new Date(e.startedAt).getTime()));

const avg_duration_ms = durations.length ? Math.round(durations.reduce((a, b) => a + b, 0) / durations.length) : 0;
const slowest_duration_ms = durations.length ? Math.max(...durations) : 0;
const slowest_index = durations.indexOf(slowest_duration_ms);
const slowest_execution_id = slowest_index >= 0 ? executions[slowest_index].id : null;

const success_rate = total ? Math.round(((total - errored) / total) * 1000) / 10 : 100;
const duration_score = Math.max(0, 100 - (avg_duration_ms / 100));
const performance_score = Math.round((success_rate * 0.6) + (duration_score * 0.4));

return [{
  json: {
    total_executions: total,
    error_rate_percentage,
    avg_duration_ms,
    slowest_duration_ms,
    slowest_execution_id,
    success_rate,
    performance_score
  }
}];
